CREATE TABLE MasterWorkspace(Id BIGINT PRIMARY KEY CHECK(Id=1),Mode NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,Version BIGINT NOT NULL);
INSERT INTO MasterWorkspace VALUES(1,'Demo',1);
CREATE TABLE MasterSkuData(SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY,Unit NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,Version BIGINT NOT NULL);
INSERT INTO MasterSkuData SELECT Id,N'件',1 FROM Skus;
CREATE TABLE MasterShopData(ShopId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY,ExternalId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,Enabled BIGINT NOT NULL CHECK(Enabled IN(0,1)),Version BIGINT NOT NULL);
INSERT INTO MasterShopData SELECT Id,Id,1,1 FROM Shops;
CREATE TABLE MasterMappingState(TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,Platform NVARCHAR(30) COLLATE Latin1_General_100_BIN2 NOT NULL,ShopId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,ProductId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,VariantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,Enabled BIGINT NOT NULL CHECK(Enabled IN(0,1)),PRIMARY KEY(TenantId,Platform,ShopId,ProductId,VariantId));
CREATE TABLE MasterHistory(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY,Entity NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,Action NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,Actor NVARCHAR(150) COLLATE Latin1_General_100_BIN2 NOT NULL,Reason NVARCHAR(500) COLLATE Latin1_General_100_BIN2 NOT NULL,CreatedAt NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,DataJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL);
CREATE INDEX IX_MasterHistory_Entity ON MasterHistory(Entity,CreatedAt);
CREATE TABLE OpeningDocuments(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY,Number NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL UNIQUE,State NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,Version BIGINT NOT NULL,CreatedBy NVARCHAR(150) COLLATE Latin1_General_100_BIN2 NOT NULL,ApprovedBy NVARCHAR(150) COLLATE Latin1_General_100_BIN2 NOT NULL,Reason NVARCHAR(500) COLLATE Latin1_General_100_BIN2 NOT NULL,CreatedAt NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,LinesJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL);
CREATE TABLE OpeningSkuClaims(SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY,DocumentId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES OpeningDocuments(Id));
CREATE TABLE WorkerHealth(Name NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY,LastSeen NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,LastSuccess NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,LastError NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,ConsecutiveErrors BIGINT NOT NULL);
ALTER TABLE DeliveryJobs ADD CycleAttempts BIGINT NOT NULL DEFAULT 0;
